INSERT INTO product_group (id, name, description, position) VALUES
  ('aluminium', 'Aluminum', 'Unwrought aluminium, semi-finished and finished products, construction profiles and packaging', '0'),
  ('textile', 'Textile', 'Apparel, accessories, footwear and home textiles', '1');
INSERT INTO legislation (id, short, title, ref, celex, category, standards_note, position) VALUES
  ('espr', 'ESPR', 'Ecodesign for Sustainable Products Regulation', 'Regulation (EU) 2024/1781', '32024R1781', 'product', NULL, '0'),
  ('cpr', 'CPR', 'Construction Products Regulation', 'Regulation (EU) 2024/3110', '32024R3110', 'product', NULL, '1'),
  ('ppwr', 'PPWR', 'Packaging and Packaging Waste Regulation', 'Regulation (EU) 2025/40', '32025R0040', 'product', NULL, '2'),
  ('cbam', 'CBAM', 'Carbon Border Adjustment Mechanism', 'Regulation (EU) 2023/956', '32023R0956', 'climate', NULL, '3'),
  ('reach', 'REACH', 'Registration, Evaluation, Authorisation and Restriction of Chemicals', 'Regulation (EC) No 1907/2006', '32006R1907', 'chemicals', NULL, '4'),
  ('bpr', 'BPR', 'Biocidal Products Regulation', 'Regulation (EU) No 528/2012', '32012R0528', 'chemicals', NULL, '5'),
  ('tlr', 'TLR', 'Textile Labelling Regulation', 'Regulation (EU) No 1007/2011', '32011R1007', 'consumer', 'The act names no standard. It refers only to the harmonised standards “to be introduced in” Annex VIII.', '6'),
  ('gpsr', 'GPSR', 'General Product Safety Regulation', 'Regulation (EU) 2023/988', '32023R0988', 'consumer', 'The act names no standard. It relies on European standards whose references are published in the Official Journal.', '7'),
  ('wfd', 'WFD', 'Waste Framework Directive', 'Directive 2008/98/EC, as amended by Directive (EU) 2025/1892', '32008L0098', 'waste', NULL, '8'),
