INSERT INTO legislation_scope (legislation_id, product_group_id, note) VALUES
  ('espr', 'aluminium', 'Aluminium is a priority intermediate product in the 2025–2030 working plan; delegated act with DPP expected around 2027.'),
  ('espr', 'textile', 'Textiles (apparel) are a priority group; delegated act expected around 2027. Ban on destroying unsold apparel and footwear from 19 July 2026.'),
  ('cpr', 'aluminium', 'Aluminium construction products (profiles, windows, curtain walling, cladding). Applies from 8 January 2026, product family by product family.'),
  ('ppwr', 'aluminium', 'Aluminium packaging (cans, foil, trays, tubes, aerosols). Applies from 12 August 2026.'),
  ('cbam', 'aluminium', 'Unwrought aluminium and aluminium products (CN 7601, 7603–7616) imported into the EU. Definitive period since 1 January 2026; importers under 50 tonnes net mass a year are exempt.'),
  ('reach', 'aluminium', 'Substances of very high concern in articles; Annex XVII restrictions that apply to metal articles.'),
  ('reach', 'textile', 'Substances of very high concern in articles; textile-specific restrictions in Annex XVII.'),
  ('bpr', 'textile', 'Treated articles, e.g. antibacterial, anti-odour or anti-mould textiles.'),
  ('tlr', 'textile', 'All textile products made available on the EU market.'),
  ('gpsr', 'textile', 'Consumer textile products. Applies since 13 December 2024.'),
  ('wfd', 'aluminium', 'SCIP notification of articles containing substances of very high concern.'),
  ('wfd', 'textile', 'SCIP notification, plus extended producer responsibility for textiles and footwear: schemes operational by April 2028.'),
  ('flr', 'aluminium', 'Ban on products made with forced labour, e.g. in bauxite mining or smelting. Applies from 14 December 2027.'),
  ('flr', 'textile', 'Ban on products made with forced labour, e.g. in cotton farming or garment making. Applies from 14 December 2027.');
