INSERT INTO standard_citation (legislation_id, standard_id, provision, force, excerpt, cited_as, source_celex, position) VALUES
  ('espr', 'en-18216-2026', 'Annex, no 1', 'operative', 'EN 18216:2026 Digital product passport – Data exchange protocols', NULL, '32026D1736', '0'),
  ('espr', 'en-18219-2026', 'Annex, no 2', 'operative', 'EN 18219:2026 Digital product passport – Unique identifiers', NULL, '32026D1736', '1'),
  ('espr', 'en-18220-2026', 'Annex, no 3', 'operative', 'EN 18220:2026 Digital product passport – Data carriers', NULL, '32026D1736', '2'),
  ('espr', 'en-18221-2026', 'Annex, no 4', 'operative', 'EN 18221:2026 Digital product passport – Data storage, archiving, and persistence', NULL, '32026D1736', '3'),
  ('espr', 'en-18222-2026', 'Annex, no 5', 'operative', 'EN 18222:2026 Digital Product Passport – Application Programming Interfaces (APIs) for product passport lifecycle management and searchability', NULL, '32026D1736', '4'),
  ('espr', 'en-18223-2026', 'Annex, no 6', 'operative', 'EN 18223:2026 Digital Product Passport – System interoperability', NULL, '32026D1736', '5'),
  ('espr', 'iso-iec-15459-6', 'Annex III(c)', 'operative', 'the Global Trade Identification Number as provided for in International Organization for Standardisation/International Electrotechnical Commission standard ISO/IEC 15459-6 or equivalent of products or their parts', 'ISO/IEC 15459-6', '32024R1781', '6'),
  ('espr', 'iso-iec-15459-1', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '7'),
  ('espr', 'iso-iec-15459-2', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '8'),
  ('espr', 'iso-iec-15459-3', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '9'),
  ('espr', 'iso-iec-15459-4', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '10'),
  ('espr', 'iso-iec-15459-5', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '11'),
  ('espr', 'iso-iec-15459-6', 'Annex III, after point (l)', 'operative', 'The data carrier, the unique product identifier referred to in point (b), the unique operator identifiers referred to in points (g), (h) and (k), and the unique facility identifiers referred to in point (i) shall, where relevant for the products concerned, comply with standards ISO/IEC 15459-1:2014, ISO/IEC 15459-2:2015, ISO/IEC 15459-3:2014, ISO/IEC 15459-4:2014, ISO/IEC 15459-5:2014 and ISO/IEC 15459-6:2014.', NULL, '32024R1781', '12'),
  ('espr', 'en-iso-14024', 'Recital 48', 'recital', 'The EU Ecolabel and other nationally or regionally officially recognised EN ISO 14024 type I ecolabels are not to be considered misleading or confusing labels', NULL, '32024R1781', '13'),
  ('cpr', 'en-15804', 'Recital 7', 'recital', 'The Commission should make available software to perform the calculation, in particular the characterisation factors applicable in accordance with European standard EN 15804 or future applicable standards.', NULL, '32024R3110', '14'),
  ('cpr', 'en-iso-14024', 'Art. 19(1)', 'operative', 'Officially recognised EN ISO 14024 type I ecolabels may be affixed to a product if they fulfil the requirement in the first subparagraph.', NULL, '32024R3110', '15'),
  ('cpr', 'en-iso-14024', 'Art. 83(7)', 'operative', 'The EU Ecolabel and other national or regional EN ISO 14024 type I ecolabelling schemes officially recognised in accordance with Article 11 of Regulation (EC) No 66/2010', NULL, '32024R3110', '16'),
  ('ppwr', 'en-13432-2000', 'Recital 55', 'recital', 'The requirements of harmonised standard EN 13432:2000 ‘Packaging – Requirements for packaging recoverable by composting and biodegradation – Test scheme and evaluation criteria for final acceptance of packaging’ should be revised', NULL, '32025R0040', '17'),
  ('ppwr', 'en-13428-2004', 'Recital 60', 'recital', 'until such time as a new or updated harmonised standard becomes available, the existing standard, EN 13428:2004, can be used.', NULL, '32025R0040', '18'),
  ('cbam', 'iso-iec-17025', 'Annex II, point B.5.4.3', 'operative', 'Laboratories used to carry out analyses for the determination of calculation factors are recommended to be accredited in accordance with ISO/IEC 17025, for the relevant analytical methods.', NULL, '32025R2547', '19'),
  ('cbam', 'iso-iec-17025', 'Annex II, point B.6.3', 'operative', 'Laboratories carrying out measurements, calibrations and relevant equipment assessments for continuous measurement systems shall be accredited in accordance with ISO/IEC 17025 for the relevant analytical methods or calibration activities.', NULL, '32025R2547', '20'),
  ('cbam', 'iso-13833', 'Annex II, point B.6.2.3', 'operative', 'a calculation-based methodology, including methodologies using analyses and sampling based on ISO 13833 (Stationary source emissions – Determination of the ratio of biomass (biogenic) and fossil-derived carbon dioxide – Radiocarbon sampling and determination)', NULL, '32025R2547', '21'),
  ('cbam', 'iso-18466', 'Annex II, point B.6.2.3', 'operative', 'another method based on a relevant standard, including ISO 18466 (Stationary source emissions – Determination of the biogenic fraction in CO2 in stack gas using the balance method)', NULL, '32025R2547', '22'),
  ('cbam', 'iso-20181-2023', 'Annex II, point B.6.3', 'operative', 'ISO 20181:2023 Stationary source emissions – Quality assurance of automated measuring systems', NULL, '32025R2547', '23'),
  ('cbam', 'iso-14164-1999', 'Annex II, point B.6.3', 'operative', 'ISO 14164:1999 Stationary source emissions – Determination of the volume flowrate of gas streams in ducts – Automated method', NULL, '32025R2547', '24'),
  ('cbam', 'iso-16911-2', 'Annex II, point B.6.3', 'operative', 'other relevant ISO standards, in particular ISO 16911-2 (Stationary source emissions – Manual and automatic determination of velocity and volume flow rate in ducts)', NULL, '32025R2547', '25'),
  ('cbam', 'ipcc-2006', 'Annex II, point B.5.2', 'operative', 'standard factors contained in the latest IPCC guidelines for GHG inventories', 'IPCC guidelines', '32025R2547', '26'),
  ('cbam', 'ipcc-2006', 'Annex II, point G, Table 1', 'operative', 'Crude oil 73,3 42,3 IPCC 2006 GL', 'IPCC 2006 GL', '32025R2547', '27'),
  ('cbam', 'iai-guidelines', 'Annex II, point B.7', 'operative', 'Emissions not related to anode effects shall be determined based on estimation methods in accordance with industry best practice, in particular guidelines provided by the International Aluminium Institute.', NULL, '32025R2547', '28'),
  ('cbam', 'iai-guidelines', 'Annex II, point B.7.1', 'operative', 'For the determination of those emission factors industry best practice shall be applied, in particular the most recent guidelines provided by the International Aluminium Institute.', NULL, '32025R2547', '29'),
  ('reach', 'iso-10156', 'Annex II, point 9.2.1(d)', 'operative', 'as per ISO 10156 ‘Gases and gas mixtures – Determination of fire potential and oxidizing ability for the selection of cylinder valve outlets’', NULL, '32006R1907', '30'),
