  ('iso-59020-2024', 'recyclability', 'textile', 'Indicators of circularity performance.', 'https://www.iso.org/standard/80650.html'),
  ('grs-5-0', 'recycled-content', 'textile', 'Certification scheme for recycled content. Textile Exchange is moving its recycled standards into a new Materials Matter Standard.', 'https://textileexchange.org/app/uploads/2020/08/GRS-101-V5.0-Global-Recycled-Standard.pdf'),
  ('asi-chain-of-custody-v2', 'recycled-content', 'aluminium', 'Lists recycled content, with its methodology, as optional data in chain-of-custody documents.', 'https://aluminium-stewardship.org/asi-standards/chain-of-custody-standard'),
  ('en-45557', 'recycled-content', 'aluminium', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45557', 'recycled-content', 'textile', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45552-2020', 'durability', 'aluminium', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45552-2020', 'durability', 'textile', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45554', 'repairability', 'textile', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45555', 'recyclability', 'aluminium', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45555', 'recyclability', 'textile', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://www.cetim.fr/en/Mecatheque/Results-of-collective-works/jtc10-material-efficiency-summary-of-standards'),
  ('en-45559-2019', 'end-of-life-info', 'aluminium', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://standards.iteh.ai/catalog/standards/sist/0310fce0-3c88-4fa4-833b-9563865ba108/sist-en-45559-2019'),
  ('en-45559-2019', 'end-of-life-info', 'textile', 'Written for energy-related products, so its method is general rather than specific to this product group.', 'https://standards.iteh.ai/catalog/standards/sist/0310fce0-3c88-4fa4-833b-9563865ba108/sist-en-45559-2019'),
  ('en-13430', 'recyclability', 'aluminium', 'Recyclability of packaging, which includes aluminium packaging.', 'https://www.productip.com/kb/academy-home/productip-library/standards-related-to-packaging'),
  ('iso-12947-2-2016', 'durability', 'textile', 'Abrasion resistance of fabrics.', 'https://www.iso.org/standard/61058.html'),
  ('iso-12945-2-2020', 'durability', 'textile', 'Pilling of fabrics.', 'https://www.iso.org/standard/75375.html'),
  ('iso-105-c06-2010', 'durability', 'textile', 'Colour fastness to laundering.', 'https://www.iso.org/standard/51276.html'),
  ('iso-13934-1-2013', 'durability', 'textile', 'Tensile strength of fabrics.', 'https://www.iso.org/standard/60676.html'),
  ('oecd-garment-footwear', 'forced-labour', 'textile', 'Due diligence for the garment and footwear sector, with a module on forced labour.', 'https://www.oecd.org/en/publications/oecd-due-diligence-guidance-for-responsible-supply-chains-in-the-garment-and-footwear-sector_9789264290587-en.html'),
  ('sa8000', 'forced-labour', 'aluminium', 'Certification scheme for workplace social accountability. Sources disagree on the latest edition, so none is stated.', 'https://sa-intl.org/?p=2242'),
  ('sa8000', 'forced-labour', 'textile', 'Certification scheme for workplace social accountability. Sources disagree on the latest edition, so none is stated.', 'https://sa-intl.org/?p=2242'),
  ('asi-performance-3-1', 'forced-labour', 'aluminium', 'Certification scheme for aluminium that covers forced labour under criterion 10.3.', 'https://aluminium-stewardship.org/forced-labour-risks-in-aluminium-how-asi-is-driving-mitigation-efforts'),
  ('iso-26000-2010', 'forced-labour', 'aluminium', 'General guidance on social responsibility.', 'https://shop.standards.ie/en-ie/standards/iso-26000-2010-598290_saig_iso_iso_1370243'),
  ('iso-26000-2010', 'forced-labour', 'textile', 'General guidance on social responsibility.', 'https://shop.standards.ie/en-ie/standards/iso-26000-2010-598290_saig_iso_iso_1370243'),
  ('iso-20400-2017', 'forced-labour', 'aluminium', 'General guidance on sustainable procurement.', 'https://evs.ee/en/iso-20400-2017'),
  ('iso-20400-2017', 'forced-labour', 'textile', 'General guidance on sustainable procurement.', 'https://evs.ee/en/iso-20400-2017'),
  ('en-iso-iec-17050-1-2010', 'conformity', 'aluminium', 'General requirements for a supplier''s declaration of conformity.', 'https://insights.snv.ch/en/page/isoiec-17050-12010-standard-overview-requirements-en'),
  ('en-iso-iec-17050-1-2010', 'conformity', 'textile', 'General requirements for a supplier''s declaration of conformity.', 'https://insights.snv.ch/en/page/isoiec-17050-12010-standard-overview-requirements-en'),
  ('iso-14064-3-2019', 'verification', 'aluminium', 'Verification of greenhouse gas statements.', 'https://www.iso.org/committee/546318/x/catalogue/'),
  ('iso-14065-2020', 'verification', 'aluminium', 'Requirements for bodies verifying environmental information.', 'https://www.iso.org/committee/546318/x/catalogue/'),
  ('iso-iec-17029-2019', 'verification', 'aluminium', 'Requirements for validation and verification bodies.', 'https://www.iso.org/news/ref2448.html'),
  ('iso-iec-17065-2012', 'verification', 'aluminium', 'Requirements for bodies certifying products. A revision is in development.', 'https://www.iso.org/standard/46568.html'),
  ('en-14351-1-2006-a2-2016', 'performance', 'aluminium', 'Performance characteristics of windows and external doors, a use of aluminium profiles.', 'https://shop.standards.ie/en-ie/standards/en-14351-1-2006-a2-2016-344407_saig_cen_cen_788127'),
  ('en-13830-2015-a1-2020', 'performance', 'aluminium', 'Performance of curtain walling, a use of aluminium profiles.', 'https://shop.standards.ie/en-ie/standards/en-13830-2015-a1-2020-345885_saig_cen_cen_2847205'),
  ('en-iec-ieee-82079-1-2020', 'instructions', 'aluminium', 'How to prepare instructions for use.', 'https://shop.standards.ie/en-ie/standards/en-iec-ieee-82079-1-2020-1185042_saig_cenelec_cenelec_2829685'),
  ('en-iec-ieee-82079-1-2020', 'instructions', 'textile', 'How to prepare instructions for use.', 'https://shop.standards.ie/en-ie/standards/en-iec-ieee-82079-1-2020-1185042_saig_cenelec_cenelec_2829685'),
  ('iso-3758-2023', 'label', 'textile', 'Care symbols on textile labels.', 'https://www.iso.org/obp/ui/#iso:std:iso:3758:ed-4:v1:en:tab:5');
INSERT INTO requirement_provision (id, data_requirement_id, legislation_id, ref, text, quotes, source_celex) VALUES
  ('1', 'product-id', 'espr', 'Art. 10(1)(a)–(b)', 'Persistent unique product identifier, reached through a data carrier on the product, packaging or documentation. Applies once the ESPR delegated act for the product group requires it.', '["it shall be connected through a data carrier to a persistent unique product identifier; (b) the data carrier shall be physically present on the product, its packaging or on documentation accompanying the product"]', NULL),
  ('2', 'product-id', 'cpr', 'Art. 22(5)', 'Unique identification code of the product type, plus batch or serial number where available, on the product.', '["The manufacturer shall ensure that its products bear a manufacturer-specific unique identification code of the product type and, where available, a batch or serial number which is easily visible and legible for users."]', NULL),
  ('3', 'product-id', 'ppwr', 'Art. 15(5)', 'Type, batch or serial number on the packaging, or in a document accompanying the packaged product.', '["Manufacturers shall ensure that the packaging bears a type, batch or serial number or other element allowing its identification"]', NULL),
  ('4', 'product-id', 'gpsr', 'Art. 9(5)', 'Type, batch or serial number or another identifying element on the product, or on its packaging or accompanying document where the product is too small.', NULL, NULL),
  ('5', 'product-id', 'flr', 'Art. 27(2)', 'At release for free circulation or export, for products or product groups named in a delegated act under Art. 27(1).', '["shall provide or make available to customs authorities information identifying the product, information about the manufacturer or the producer and information about the product suppliers"]', NULL),
  ('6', 'commodity-code', 'espr', 'Annex III(d)', 'Commodity code of the product in the digital product passport; Art. 13(1) also stores it in the registry for goods released for free circulation. Applies once the ESPR delegated act for the product group requires it.', '["relevant commodity codes, such as a TARIC code as defined in Regulation (EEC) No 2658/87"]', NULL),
  ('7', 'commodity-code', 'cbam', 'Annex I', 'CBAM goods are identified by CN code: aluminium is 7601 and 7603 to 7616. The declaration reports per type of goods.', '["7601 – Unwrought aluminium","7616 – Other articles of aluminium"]', NULL),
  ('8', 'manufacturer', 'espr', 'Annex III(g)', 'Manufacturer identity and contact details, with its unique operator identifier. Applies once the ESPR delegated act for the product group requires it.', '["information related to the manufacturer, such as its unique operator identifier and the information referred to in Article 27(7)"]', NULL),
  ('9', 'manufacturer', 'cpr', 'Annex IV, point 1.3; Art. 18(2)(b)', 'Part of the general product information; the CE marking is also followed by the manufacturer''s name and registered address.', '["Contact details of the manufacturer or the authorised representative: (a) name; (b) postal address; (c) telephone; (d) email address; (e) website, where available."]', NULL),
  ('10', 'manufacturer', 'ppwr', 'Art. 15(6)', 'Manufacturer name and postal address on the packaging or through its data carrier.', '["Manufacturers shall indicate on the packaging or on a QR code or another data carrier their name, registered trade name or registered trademark as well as the postal address at which and, where available, the electronic means of communication by which they can be contacted."]', NULL),
  ('11', 'manufacturer', 'gpsr', 'Art. 9(6)', 'Name, registered trade name or trade mark, and postal and electronic address of the manufacturer on the product or its packaging.', NULL, NULL),
  ('12', 'manufacturer', 'flr', 'Art. 27(2)', 'Given to customs for products or product groups named in a delegated act under Art. 27(1).', '["information about the manufacturer or the producer"]', NULL),
  ('13', 'importer', 'espr', 'Annex III(j)–(k)', 'Importer details with EORI number, and the EU-established operator responsible for the product. Applies once the ESPR delegated act for the product group requires it.', '["information related to the importer, including the information referred to in Article 29(3) and its Economic Operators Registration and Identification (EORI) number; (k) the name, contact details and unique operator identifier of the economic operator established in the Union responsible for carrying out the tasks set out in Article 4 of Regulation (EU) 2019/1020"]', NULL),
  ('14', 'importer', 'cbam', 'Art. 5(1) as amended; Annex V, point 1.1', 'Only an authorised CBAM declarant may import CBAM goods. Records must identify the declarant by name and CBAM account number (Annex V). Importers under 50 tonnes net mass a year are exempt (Art. 2a).', '["Any importer established in a Member State shall, prior to importing goods into the customs territory of the Union, apply for the status of authorised CBAM declarant"]', '32025R2083'),
  ('15', 'importer', 'cpr', 'Art. 24(6)', 'Importer name and contact address on the product, its packaging or accompanying document.', '["importer shall indicate its name, registered trade name or registered trade mark, its place of business, its contact address and, where available, electronic means of communication, either on the product or, where that is not possible, on its packaging, or in a document accompanying the product."]', NULL),
  ('16', 'importer', 'ppwr', 'Art. 18(3)', 'Importer name and postal address on the packaging, or through its data carrier or an accompanying document.', '["Importers shall indicate on the packaging their name and their registered trade name or registered trademark as well as the postal address at which and, where available, the electronic means of communication by which they can be contacted."]', NULL),
  ('17', 'importer', 'gpsr', 'Art. 11; Art. 4 of Reg. (EU) 2019/1020', 'Name and contact details of the importer on the product, and an EU-established responsible economic operator identified on the product.', NULL, NULL),
  ('18', 'producer-registration', 'ppwr', 'Art. 44(2)', 'Registration in the national register of producers of each Member State where the packaging is first made available.', '["Producers shall be obliged to register in the register referred to in paragraph 1 of this Article in each Member State where they make packaging or packaged products available on the territory of the Member State for the first time"]', NULL),
  ('19', 'producer-registration', 'wfd', 'Art. 22b (textile EPR)', 'Producers of textile, textile-related and footwear products register in each Member State where they make them available, and show the registration number to buyers.', NULL, NULL),
  ('20', 'material-composition', 'espr', 'Annex I(d)', 'Material composition as a parameter of design for recycling. Applies once the ESPR delegated act for the product group requires it.', '["material composition and homogeneity, possibility for high-purity sorting"]', NULL),
  ('21', 'material-composition', 'cpr', 'Annex IV, point 1.2(e)', 'Main materials, as part of the product description in the general product information.', '["main materials used."]', NULL),
  ('22', 'material-composition', 'ppwr', 'Art. 12(1)', 'From 12 August 2028, or 24 months after the implementing acts, whichever is later.', '["packaging placed on the market shall be marked with a harmonised label containing information on its material composition in order to facilitate consumer sorting."]', NULL),
  ('23', 'material-composition', 'tlr', 'Arts. 5, 9, 11', 'Fibre composition by percentage of weight using only the fibre names in Annex I; multi-fibre and multi-component products declared per component.', NULL, NULL),
  ('24', 'animal-origin', 'tlr', 'Art. 12', 'Products containing non-textile parts of animal origin (e.g. leather, fur) state “Contains non-textile parts of animal origin”.', NULL, NULL),
  ('25', 'substances-of-concern', 'espr', 'Art. 7(5)', 'Name (IUPAC, EC, CAS), location and concentration of each substance of concern, plus safe-use and end-of-life information. Applies once the ESPR delegated act for the product group requires it.', '["the information requirements shall make it possible to track the substances of concern, throughout the life cycle of the products concerned","the name or numerical code of the substances of concern present in the product","the location of the substances of concern within the product;","the concentration, maximum concentration or concentration range of the substances of concern, at the level of the product, its relevant components, or spare parts;"]', NULL),
  ('26', 'substances-of-concern', 'reach', 'Art. 33(1)', 'Candidate List substances above 0.1 % w/w: inform recipients; consumers on request within 45 days (Art. 33(2)).', '["Any supplier of an article containing a substance meeting the criteria in Article 57 and identified in accordance with Article 59(1) in a concentration above 0,1 % weight by weight (w/w) shall provide the recipient of the article with sufficient information, available to the supplier, to allow safe use of the article including, as a minimum, the name of that substance."]', NULL),
  ('27', 'substances-of-concern', 'reach', 'Art. 7(2)', 'Notify ECHA when a Candidate List substance is in the articles above 0.1 % w/w and above 1 tonne a year.', '["Any producer or importer of articles shall notify the Agency, in accordance with paragraph 4 of this Article, if a substance meets the criteria in Article 57 and is identified in accordance with Article 59(1)","the substance is present in those articles in quantities totalling over one tonne per producer or importer per year;","the substance is present in those articles above a concentration of 0,1 % weight by weight (w/w)."]', NULL),
  ('28', 'substances-of-concern', 'wfd', 'Art. 9(1)(i)', 'The REACH Art. 33(1) information goes to ECHA''s SCIP database.', '["ensure that any supplier of an article as defined in point 33 of Article 3 of Regulation (EC) No 1907/2006","provides the information pursuant to Article 33(1) of that Regulation to the European Chemicals Agency as from 5 January 2021;"]', '32018L0851'),
  ('29', 'substances-of-concern', 'cpr', 'Art. 15(6)', 'The REACH safety data sheet or Art. 33 information is supplied with the declaration of performance and conformity.', '["The information referred to in Article 31 or, as the case may be, in Article 33 of Regulation (EC) No 1907/2006","shall be provided together with the declaration of performance and conformity."]', NULL),
  ('30', 'substances-of-concern', 'ppwr', 'Arts. 5(1), 12(1)', 'Substances of concern minimised, and packaging containing them digitally marked.', '["Packaging placed on the market shall be so manufactured that the presence and concentration of substances of concern as constituents of the packaging material or of any of the packaging components is minimised","The packaging placed on the market containing substances of concern shall be marked by means of standardised, open, digital-marking technologies"]', NULL),
  ('31', 'restricted-substances', 'reach', 'Annex XVII', 'Compliance with textile restrictions: azo dyes (entry 43), nonylphenol ethoxylates (46a), dimethylfumarate (61), CMR substances in clothing and textiles (72), PFHxA (79).', NULL, NULL),
  ('32', 'restricted-substances', 'ppwr', 'Art. 5(4)–(5)', 'Heavy-metal sum limit for all packaging; PFAS limits for food-contact packaging.', '["the sum of the concentrations of lead, cadmium, mercury and hexavalent chromium resulting from substances present in packaging or packaging components shall not exceed 100 mg/kg.","From 12 August 2026, food-contact packaging shall not be placed on the market if it contains per- and polyfluorinated alkyl substances (PFAS) in a concentration equal to or above the following limit values"]', NULL),
  ('33', 'biocidal-treatment', 'bpr', 'Art. 58(3)', 'Treated articles state that they incorporate biocidal products, the biocidal property claimed, the active substances and any nanomaterials (marked “(nano)”).', NULL, NULL),
  ('34', 'carbon-footprint', 'espr', 'Art. 7(2)(b)(i); Annex I(n)', 'Carbon footprint, calculated with the method the delegated act sets. Applies once the ESPR delegated act for the product group requires it.', '["information on the performance of the product in relation to one or more of the product parameters referred to in Annex I, including a repairability score, a durability score, a carbon footprint or an environmental footprint;","the carbon footprint of the product;"]', NULL),
  ('35', 'carbon-footprint', 'cbam', 'Art. 6(2)(b); Art. 7(1)', 'Aluminium is in Annex II, so only direct embedded emissions count. They come from actual installation data or default values (Art. 7(2) as amended).', '["the total embedded emissions in the goods referred to in point (a) of this paragraph, expressed in tonnes of CO2e emissions per megawatt-hour of electricity or, for other goods, in tonnes of CO2e emissions per tonne of each type of goods","For goods listed in Annex II only direct emissions shall be calculated and taken into account."]', NULL),
  ('36', 'carbon-footprint', 'cpr', 'Art. 15(2)–(3)(a); Annex II(a)–(d)', 'Life-cycle climate change effects (total, fossil, biogenic, land use) declared in the DoPC, calculated with the Commission''s free software.', '["The declaration of performance and conformity shall include the product’s environmental sustainability performance over its life cycle in respect of the predetermined environmental essential characteristics listed in Annex II for those characteristics that are declared.","essential characteristics listed in points (a) to (d) of Annex II, from 8 January 2026;","climate change effects – total;"]', NULL),
  ('37', 'environmental-footprint', 'espr', 'Annex I(m)', 'Applies once the ESPR delegated act for the product group requires it.', '["the environmental footprint of the product, expressed as a quantification, in accordance with the applicable delegated act, of a product’s life cycle environmental impacts, whether in relation to one or more environmental impact categories or an aggregated set of impact categories;"]', NULL),
  ('38', 'environmental-footprint', 'cpr', 'Art. 15(3)(b)–(c); Annex II(e)–(s)', 'Further life-cycle indicators in the DoPC: ozone depletion, acidification, eutrophication, resource depletion and water use from 2030; particulate matter, toxicity and land use from 2032.', '["essential characteristics listed in points (e) to (m), of Annex II, from 9 January 2030;","essential characteristics listed in points (n) to (s), of Annex II, from 9 January 2032."]', NULL),
  ('39', 'process-emissions', 'espr', 'Annex I(q)', 'Applies once the ESPR delegated act for the product group requires it.', '["emissions to air, water or soil released in one or more lifecycle stages of the product as expressed through quantities and nature of emissions"]', NULL),
  ('40', 'process-emissions', 'cbam', 'Annex I, point 3.17.2.1', 'Primary (electrolytic) smelting: monitor CO₂ from anode consumption and PFCs (CF₄, C₂F₆) from anode effects. Secondary melting covers fuel emissions only (point 3.17.2.2).', '["all processes directly or indirectly linked to the production processes emitting CO2 emissions from the consumption of electrodes or electrode pastes;","perfluorocarbon emissions caused by anode effects monitored in accordance with point B.7 of Annex II."]', '32025R2547'),
  ('41', 'energy-resources', 'espr', 'Annex I(g)', 'Applies once the ESPR delegated act for the product group requires it.', '["use or consumption of energy, water and other resources in one or more life cycle stages of the product"]', NULL),
  ('42', 'precursors', 'cbam', 'Annex VI, point 2(k)', 'Complex goods (e.g. aluminium products made from unwrought aluminium) carry the embedded emissions of their precursors; the verification report states them.', '["quantities of each input material (precursor) used;","the specific embedded emissions associated with each of the input materials (precursors) used;"]', NULL),
  ('43', 'carbon-price', 'cbam', 'Art. 9(1)–(2) as amended', 'Optional reduction, backed by documentation certified by an independent person; with default values, only yearly default carbon prices can be used (Art. 9(4)).', '["Where the embedded emissions are determined on the basis of actual emissions, an authorised CBAM declarant may claim in the CBAM declaration a reduction in the number of CBAM certificates to be surrendered in order to take into account the carbon price paid in a third country for the declared embedded emissions.","The authorised CBAM declarant shall also keep evidence of the actual payment of the carbon price."]', '32025R2083'),
  ('44', 'microplastics', 'espr', 'Annex I(p)', 'Microplastic release, e.g. fibre shedding during washing, per relevant life-cycle stage.', NULL, NULL),
  ('45', 'recycled-content', 'espr', 'Annex I(h)', 'Applies once the ESPR delegated act for the product group requires it.', '["use or content of recycled materials and recovery of materials, including critical raw materials;"]', NULL),
  ('46', 'recycled-content', 'cbam', 'Annex I, point 3.17.2.2; Annex II, section F', 'No recycled-content share is declared, but the production route (primary or secondary) must be known: scrap enters with zero embedded emissions.', '["Secondary melting (recycling) of aluminium uses aluminium scrap as main input.","Off-spec products, by-products, waste, and scrap produced in a production process, irrespective of whether they are returned to production processes, delivered to other installations, or disposed of, shall not be included in the determination of the activity level. They shall therefore be assigned zero embedded emissions when entering another production process."]', '32025R2547'),
  ('47', 'durability', 'espr', 'Annex I(a)', 'Durability and reliability, e.g. guaranteed or technical lifetime, resistance to stresses or ageing (pilling, colour fastness, seam strength).', NULL, NULL),
  ('48', 'durability', 'cpr', 'Annex IV, point 1.2(d)', 'Part of the product description in the general product information.', '["estimated average and minimum service life span for declared use (durability);"]', NULL),
  ('49', 'durability', 'wfd', 'Textile EPR, fee modulation', 'EPR fees modulated by ecodesign criteria such as durability and reparability, aligned with ESPR requirements.', NULL, NULL),
  ('50', 'repairability', 'espr', 'Annex I(b)', 'Ease of repair and maintenance: spare parts, repair instructions, non-destructive disassembly.', NULL, NULL),
  ('51', 'recyclability', 'espr', 'Annex I(d)', 'Applies once the ESPR delegated act for the product group requires it.', '["design for recycling, ease and quality of recycling as expressed through use of easily recyclable materials"]', NULL),
  ('52', 'recyclability', 'ppwr', 'Art. 6(1), (3)', 'Grades A–C required from 2030 (or 24 months after the delegated acts); only A or B from 2038.', '["All packaging placed on the market shall be recyclable.","Packaging recyclability shall be expressed in the recyclability performance grades A, B or C as described in Table 3 of Annex II."]', NULL),
  ('53', 'recyclability', 'wfd', 'Textile EPR, fee modulation', 'EPR fees modulated by recyclability and recycled content of the textile products.', NULL, NULL),
  ('54', 'end-of-life-info', 'espr', 'Art. 7(2)(b)(iii)', 'Applies once the ESPR delegated act for the product group requires it.', '["information for treatment facilities on disassembly, reuse, refurbishment, recycling, or disposal at end-of-life;"]', NULL),
  ('55', 'end-of-life-info', 'cpr', 'Annex IV, point 1.4(a)', 'Contact point for deconstruction and demolition information, where different from the manufacturer''s contact details.', '["information on installation, maintenance, use, deconstruction and demolition;"]', NULL),
  ('56', 'end-of-life-info', 'ppwr', 'Art. 12(1)', 'Optional, in addition to the mandatory harmonised sorting label.', '["economic operators may place a QR code or other type of standardised, open, digital data carrier on the packaging that contains information on the destination of each separate component of the packaging in order to facilitate consumer sorting."]', NULL),
  ('57', 'end-of-life-info', 'wfd', 'Textile EPR', 'Consumers informed about reuse, separate collection points and proper discarding of used textiles.', NULL, NULL),
  ('58', 'quantities', 'cbam', 'Art. 6(2)(a) as amended', 'In the annual CBAM declaration, due by 30 September for the preceding year (first in 2027 for 2026).', '["the total quantity of each type of goods imported during the preceding calendar year, expressed in megawatt-hours for electricity and in tonnes for other goods, including the imported goods below the single mass-based threshold;"]', '32025R2083'),
  ('59', 'quantities', 'ppwr', 'Art. 44(7); Annex IX, Part B, point 1(c)', 'Reported to the register of producers by 1 June for the preceding year.', '["quantities by weight of packaging categories as set out in Table 1 of Annex II that the producer makes available on the territory of the Member State for the first time"]', NULL),
  ('60', 'quantities', 'wfd', 'Textile EPR', 'Quantities of textile, textile-related and footwear products made available on the market, reported per Member State.', NULL, NULL),
  ('61', 'unsold-products', 'espr', 'Arts. 24–25, Annex VII', 'Large enterprises disclose the number and weight of unsold products discarded, with reasons and destination; destroying unsold apparel and footwear banned from 19 July 2026.', NULL, NULL),
  ('62', 'production-site', 'espr', 'Annex III(i)', 'Applies once the ESPR delegated act for the product group requires it.', '["unique facility identifiers;"]', NULL),
  ('63', 'production-site', 'cbam', 'Annex V, points 1.2(b) and 2(a)', 'Records kept by the declarant; the installation is needed whenever actual emissions are used.', '["country of origin;","identification of the installation where the goods were produced;"]', NULL),
  ('64', 'production-site', 'cbam', 'Art. 10(2)(b)', 'When the third-country operator registers its installation in the CBAM registry.', '["the location of each installation including the complete address and geographical coordinates expressed in longitude and latitude, including six decimals;"]', NULL),
  ('65', 'supply-chain-operators', 'espr', 'Annex III(h)', 'Applies once the ESPR delegated act for the product group requires it.', '["unique operator identifiers other than that of the manufacturer;"]', NULL),
  ('66', 'supply-chain-operators', 'cbam', 'Art. 10(2)(a) as amended', 'Third-country installation operators register in the CBAM registry and can share verified emissions with declarants (Art. 10(7)).', '["the name, address, corporate or activity registration number and contact information of the operator, and, if applicable, of its controlling entities including the parent company of that operator, together with the supporting documents;"]', '32025R2083'),
  ('67', 'supply-chain-operators', 'flr', 'Art. 27(2)', 'Given to customs for products or product groups named in a delegated act under Art. 27(1).', '["information about the product suppliers"]', NULL),
  ('68', 'forced-labour', 'flr', 'Arts. 3, 17(1)–(2)', 'Applies from 14 December 2027. When assessed, operators answer within 30 working days on their due diligence.', '["Economic operators shall not place or make available on the Union market products that are made with forced labour, nor shall they export such products.","the relevant actions they have taken in order to identify, prevent, mitigate, bring to an end or remediate risks of forced labour in their operations and supply chains with respect to the products under assessment"]', NULL),
  ('69', 'conformity', 'espr', 'Annex III(e)', 'Applies once the ESPR delegated act for the product group requires it.', '["compliance documentation and information required under this Regulation or other Union law applicable to the product, such as the declaration of conformity, technical documentation or conformity certificates;"]', NULL),
  ('70', 'conformity', 'cpr', 'Art. 15(1)', 'Declaration of performance and conformity (DoPC), drawn up on the Annex V model.', '["The declaration of performance and conformity shall express the performance of products in relation to the essential characteristics of those products in accordance with the relevant harmonised technical specifications or European assessment document."]', NULL),
  ('71', 'conformity', 'ppwr', 'Arts. 15(2), 39(1)', 'Technical documentation and EU declaration of conformity, kept 5 years (single-use) or 10 years (reusable).', '["Before placing packaging on the market, manufacturers shall carry out the conformity assessment procedure referred to in Article 38 or have it carried out on their behalf, and shall draw up the technical documentation referred to in Annex VII.","The EU declaration of conformity shall state that the fulfilment of the requirements laid down in or pursuant to Articles 5 to 12 has been demonstrated."]', NULL),
  ('72', 'conformity', 'gpsr', 'Art. 9(2)–(3)', 'Internal risk analysis and technical documentation, kept for 10 years after the product is placed on the market.', NULL, NULL),
  ('73', 'verification', 'cbam', 'Art. 8(1) as amended', 'Not needed when default values are used. The verification report goes with the declaration (Art. 6(2)(d)).', '["Where the embedded emissions are determined on the basis of actual emissions, the authorised CBAM declarant shall ensure that the total embedded emissions declared in the CBAM declaration submitted pursuant to Article 6 are verified by a verifier accredited pursuant to Article 18, based on the verification principles set out in Annex VI."]', '32025R2083'),
  ('74', 'verification', 'cpr', 'Art. 10(1)', 'Assessment and verification system set per product family; may involve a notified body.', '["shall be carried out in accordance with one or more of the systems set out in Annex IX."]', NULL),
  ('75', 'performance', 'espr', 'Annex I(s)', 'Applies once the ESPR delegated act for the product group requires it.', '["functional performance and conditions for use"]', NULL),
  ('76', 'performance', 'cpr', 'Art. 22(1)', 'Essential characteristics come from the harmonised technical specification for the product family.', '["The manufacturer shall ensure that the product’s performance is assessed in relation to both mandatory essential characteristics and those essential characteristics intended to be declared."]', NULL),
  ('77', 'dpp', 'espr', 'Arts. 9(1), 10(4), 13(4)', 'Applies once the ESPR delegated act for the product group requires it.', '["products can only be placed on the market or put into service if a digital product passport is available in accordance with the applicable delegated acts adopted pursuant to Article 4 and with Articles 10 and 11.","The economic operator, when placing the product on the market, shall make available a back-up copy of the digital product passport through a digital product passport service provider.","The economic operator placing the product on the market or putting it into service shall upload, in the registry, the data referred to in paragraphs 1 and 2."]', NULL),
  ('78', 'dpp', 'cpr', 'Art. 22(7); Art. 76(2)', 'The passport carries the DoPC, general product information and instructions, technical documentation, label and unique identifiers.', '["By 18 months after the entry into force of the delegated act referred to in Article 75(1) the manufacturer shall make available a digital product passport referred to in Article 76, through the construction digital product passport system referred to in Article 75, connected to a data carrier referred to in Article 18(2), point (g)."]', NULL),
  ('79', 'instructions', 'espr', 'Annex III(f)', 'Applies once the ESPR delegated act for the product group requires it.', '["user manuals, instructions, warnings or safety information, as required by other Union law applicable to the product;"]', NULL),
  ('80', 'instructions', 'cpr', 'Art. 22(6); Annex IV', 'Covers safety in transport, installation, maintenance and demolition, compatibility, maintenance needs and safe use.', '["When making a product available on the market, the manufacturer shall ensure that it is accompanied by general product information, instructions for use and safety information, as set out in Annex IV in a language to be determined by the Member State concerned or, in absence of such determination, in a language which can be easily understood by users."]', NULL),
  ('81', 'instructions', 'gpsr', 'Art. 9(7)', 'Clear instructions and safety information in a language consumers easily understand.', NULL, NULL),
  ('82', 'instructions', 'bpr', 'Art. 58(3)', 'Instructions for use and precautions for the treated article where needed to protect people or the environment.', NULL, NULL),
  ('83', 'label', 'tlr', 'Arts. 14–16', 'Durable, legible and accessible label or marking in the language of the Member State where sold, visible before purchase including online.', NULL, NULL),
  ('84', 'label', 'bpr', 'Art. 58(3)', 'Label on the treated article itself, or its packaging, in the official language of the Member State.', NULL, NULL),
  ('85', 'label', 'cpr', 'Art. 18(1)–(2)', 'The CE marking is followed by the year, manufacturer, product-type code, DoPC code, notified body number and a data carrier.', '["The CE marking shall be affixed visibly, legibly and indelibly to the product.","the unique identification code of the product-type;","the declaration code of the declaration of performance and conformity;"]', NULL),
  ('86', 'label', 'ppwr', 'Art. 12(1)', 'Harmonised packaging label from 12 August 2028, or 24 months after the implementing acts.', '["The label shall be based on pictograms and be easily understandable, including for persons with disabilities."]', NULL);
